	array(
		'question_text'  => 'A therapist receives an out-of-state attorney’s subpoena demanding the complete psychotherapy record. A clinician friend says, “A subpoena means you must send everything today.” What should the therapist do first?',
		'option_a'       => 'Send the entire file immediately because any subpoena overrides California confidentiality',
