	array(
		'question_text'  => 'An employer asks a therapist to continue treating an employee and also conduct a fitness-for-duty evaluation for the employer. What should the therapist do first?',
		'option_a'       => 'Assess the conflict between treatment and employer-evaluation duties, clarify the proposed information use, and separate the roles if possible',
