	array(
		'question_text'  => 'In a rural community, a clinician realizes that a new client also serves on a local nonprofit board with the clinician. No alternate provider is reasonably available. What is the best response?',
		'option_a'       => 'Assess the actual conflict and exploitation risk, discuss foreseeable limits and alternatives, use safeguards and consultation, document the decision, and monitor the relationship',
